CREATE TABLE loot_schema(version INTEGER PRIMARY KEY);
INSERT INTO loot_schema VALUES(1);
CREATE TABLE loot_keys(id TEXT PRIMARY KEY,tier TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('ISSUED','USED')),created INTEGER NOT NULL);
CREATE TABLE loot_parcels(id TEXT PRIMARY KEY,owner TEXT NOT NULL,payload BLOB NOT NULL,state TEXT NOT NULL CHECK(state IN ('WAITING','DELIVERING','DELIVERED')),source TEXT UNIQUE NOT NULL,available INTEGER NOT NULL,created INTEGER NOT NULL);
CREATE INDEX loot_pending ON loot_parcels(owner,state,available);
CREATE TABLE loot_openings(id TEXT PRIMARY KEY,player TEXT NOT NULL,tier TEXT NOT NULL,origin TEXT NOT NULL,reward TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE loot_crates(world TEXT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,tier TEXT NOT NULL,PRIMARY KEY(world,x,y,z));
CREATE TABLE loot_vaults(id TEXT PRIMARY KEY,world TEXT NOT NULL,x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,tier TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('PLANNED','ACTIVE','CLAIMED','CLEANUP','REMOVED')),expires INTEGER NOT NULL,claimed_by TEXT,claimed_at INTEGER);
CREATE UNIQUE INDEX loot_vault_location ON loot_vaults(world,x,y,z) WHERE state IN ('PLANNED','ACTIVE');
CREATE TABLE loot_vault_blocks(vault TEXT NOT NULL REFERENCES loot_vaults(id),x INTEGER NOT NULL,y INTEGER NOT NULL,z INTEGER NOT NULL,original TEXT NOT NULL,placed TEXT NOT NULL,PRIMARY KEY(vault,x,y,z));
CREATE TABLE loot_settings(name TEXT PRIMARY KEY,value TEXT NOT NULL);
